def transform(grid):
    h, w = len(grid), len(grid[0])
    background = max(
        {v for row in grid for v in row},
        key=lambda v: sum(row.count(v) for row in grid)
    )
    out = [[background for _ in range(2 * w)] for _ in range(2 * h)]
    for r in range(h):
        for c in range(w):
            out[r][c] = grid[r][c]
    return out
